DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='regional_manual_assignment_check';f:=replace(f,'IF driver_areas IS NOT NULL AND','IF jsonb_array_length(coalesce(driver_areas->''areas'',''[]''))>0 AND');f:=replace(f,'IF vehicle_areas IS NOT NULL AND','IF jsonb_array_length(coalesce(vehicle_areas->''areas'',''[]''))>0 AND');f:=replace(f,'interval_value:=public.regional_trip_interval','IF _t.pickup_timezone IS NULL OR _t.dropoff_timezone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_t.pickup_timezone) OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_t.dropoff_timezone) THEN RAISE EXCEPTION ''Pickup and destination IANA timezone review required'';END IF; interval_value:=public.regional_trip_interval');f:=replace(f,'IF _t.pickup_state<>_t.dropoff_state THEN','IF _t.pickup_state<>_t.dropoff_state THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(_t.regional_time_events,''[]'')) e WHERE e->>''kind''=''dropoff'' AND e->>''status''=''resolved'' AND e->>''timezone''=_t.dropoff_timezone) THEN RAISE EXCEPTION ''Explicit destination local date and time required for cross-state assignment'';END IF;');f:=replace(f,'NOT _t.pickup_state=ANY','NOT coalesce(_t.pickup_state,'''')=ANY');f:=replace(f,'NOT _t.dropoff_state=ANY','NOT coalesce(_t.dropoff_state,'''')=ANY');f:=replace(f,'NOT _t.pickup_county=ANY','NOT coalesce(_t.pickup_county,'''')=ANY');f:=replace(f,'NOT _t.dropoff_county=ANY','NOT coalesce(_t.dropoff_county,'''')=ANY');f:=replace(f,'NOT _t.pickup_city=ANY','NOT coalesce(_t.pickup_city,'''')=ANY');f:=replace(f,'NOT _t.dropoff_city=ANY','NOT coalesce(_t.dropoff_city,'''')=ANY');f:=replace(f,'NOT _t.pickup_zip=ANY','NOT coalesce(_t.pickup_zip,'''')=ANY');f:=replace(f,'NOT _t.dropoff_zip=ANY','NOT coalesce(_t.dropoff_zip,'''')=ANY');f:=replace(f,'NOT public.florida_county_region(_t.pickup_county)=ANY','NOT coalesce(public.florida_county_region(_t.pickup_county),'''')=ANY');f:=replace(f,'NOT public.florida_county_region(_t.dropoff_county)=ANY','NOT coalesce(public.florida_county_region(_t.dropoff_county),'''')=ANY');EXECUTE f; END $$;